Here is the root cause:
IRQ requested before power supply registration, causing a race condition during device removal where an interrupt may call power_supply_changed() with a freed power_supply handle.

Here is the patch:

 static int sbs_probe(struct i2c_client *client)
 {
 	struct sbs_info *chip;
 	struct power_supply_desc *sbs_desc;
 	struct sbs_platform_data *pdata = client->dev.platform_data;
 	struct power_supply_config psy_cfg = {};
 	int rc;
 	int irq;

 	sbs_desc = devm_kmemdup(&client->dev, &sbs_default_desc,
 			sizeof(*sbs_desc), GFP_KERNEL);
 	if (!sbs_desc)
 		return -ENOMEM;

 	sbs_desc->name = devm_kasprintf(&client->dev, GFP_KERNEL, "sbs-%s",
 			dev_name(&client->dev));
 	if (!sbs_desc->name)
 		return -ENOMEM;

 	chip = devm_kzalloc(&client->dev, sizeof(struct sbs_info), GFP_KERNEL);
 	if (!chip)
 		return -ENOMEM;

 	chip->flags = (uintptr_t)i2c_get_match_data(client);
 	chip->client = client;
 	psy_cfg.fwnode = dev_fwnode(&client->dev);
 	psy_cfg.drv_data = chip;
 	chip->last_state = POWER_SUPPLY_STATUS_UNKNOWN;
 	sbs_invalidate_cached_props(chip);
 	mutex_init(&chip->mode_lock);

 	/* use pdata if available, fall back to DT properties,
 	 * or hardcoded defaults if not
 	 */
 	rc = device_property_read_u32(&client->dev, "sbs,i2c-retry-count",
 				      &chip->i2c_retry_count);
 	if (rc)
 		chip->i2c_retry_count = 0;

 	rc = device_property_read_u32(&client->dev, "sbs,poll-retry-count",
 				      &chip->poll_retry_count);
 	if (rc)
 		chip->poll_retry_count = 0;

 	if (pdata) {
 		chip->poll_retry_count = pdata->poll_retry_count;
 		chip->i2c_retry_count  = pdata->i2c_retry_count;
 	}
 	chip->i2c_retry_count = chip->i2c_retry_count + 1;

 	chip->charger_broadcasts = !device_property_read_bool(&client->dev,
 					"sbs,disable-charger-broadcasts");

 	chip->gpio_detect = devm_gpiod_get_optional(&client->dev,
 			"sbs,battery-detect", GPIOD_IN);
 	if (IS_ERR(chip->gpio_detect))
 		return dev_err_probe(&client->dev, PTR_ERR(chip->gpio_detect),
 				     "Failed to get gpio\n");

 	i2c_set_clientdata(client, chip);

